208	// is off. It emits the escape itself rather than delegating to lipgloss because
209	// lipgloss resolves colour from a process-global profile bound to os.Stdout —
210	// which is neither the stream we are writing to nor stable under `go test`.
211	func (r *Renderer) Paint(c lipgloss.Color, s string) string {
212		if r == nil || !r.caps.Color || s == "" {
213			return s
214		}
215		seq := ansiForeground(c)
216		if seq == "" {
217			return s
218		}
219		return seq + s + "\x1b[0m"
220	}
