46	func newHostedFakeServer(t *testing.T, fake *hostedFake) *httptest.Server {
47		t.Helper()
48		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
49			fake.mu.Lock()
50			defer fake.mu.Unlock()
51			fake.requests++
52			w.Header().Set("Content-Type", "application/json")
53			switch {
54			case strings.Contains(r.URL.Path, "/brain/facts/proposals"):
55				w.WriteHeader(http.StatusNotFound)
56			case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
57				resp := map[string]any{"found": fake.ref != "", "ref": fake.ref, "version": 1, "data": fake.data}
58				if fake.authors != nil {
59					resp["authors"] = fake.authors
60				}
61				_ = json.NewEncoder(w).Encode(resp)
62			case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts/advance"):
63				var body struct {
64					Branch string `json:"branch"`
65					OldRef string `json:"oldRef"`
66					Data   []byte `json:"data"`
67				}
68				if err := json.NewDecoder(r.Body).Decode(&body); err != nil || len(body.Data) == 0 {
69					w.WriteHeader(http.StatusBadRequest)
70					return
71				}
72				if fake.denyPush {
73					w.WriteHeader(http.StatusForbidden)
74					return
75				}
76				if body.OldRef != fake.ref {
77					w.WriteHeader(http.StatusPreconditionFailed)
78					return
79				}
80				fake.seq++
81				fake.ref = fmt.Sprintf("facts-%d", fake.seq)
82				fake.data = body.Data
83				_ = json.NewEncoder(w).Encode(map[string]any{"newRef": fake.ref, "version": fake.seq, "changed": true})
84			default:
85				w.WriteHeader(http.StatusNotFound)
86			}
87		}))
