14	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
15	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
16	// and its cell API base URL, both top-level fields.
17	type hostedPlacement struct {
18		RepoID string `json:"repoId"`
19		APIURL string `json:"apiUrl"`
20	}
21	
22	type connectOptions struct {
23		repoID string
24		apiURL string
25	}
26	
27	func newConnectCommand(opts Options) *cobra.Command {
28		var connectOpts connectOptions
29		cmd := &cobra.Command{
30			Use:   "connect",
31			Short: "Bind this repository to its hosted brain explicitly",
32			Long: `connect binds this repository to its hosted brain: it records the repo id and
33	API base URL (non-secrets only — the host CLI's own login mints a fresh token
34	per sync), then runs one immediate sync so the first pull happens right away.
35	
36	Running connect is OPTIONAL: the daemon and session-end hook resolve the
37	binding automatically through the host CLI (entire repo view) and fall back
38	to local-only until that succeeds. Use connect to bind explicitly — a
39	non-default cell, a staging target, or to re-join after 'entire brain
40	disconnect'. Pass --repo-id and --api-url to bypass resolution entirely.`,
41			Args: cobra.NoArgs,
42			RunE: func(cmd *cobra.Command, args []string) error {
43				return runConnect(cmd, opts, connectOpts)
44			},
45		}
46		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
47		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
48		return cmd
49	}
50	
51	func runConnect(cmd *cobra.Command, opts Options, connectOpts connectOptions) error {
52		ctx := cmd.Context()
53		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
54		if err != nil {
55			return err
56		}
57		if !local {
58			return fmt.Errorf("connect requires a local repository path")
59		}
60		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
61		if err != nil {
62			return err
63		}
64	
65		repoID := strings.TrimSpace(connectOpts.repoID)
66		apiURL := strings.TrimSpace(connectOpts.apiURL)
67		if repoID == "" || apiURL == "" {
68			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
69			if placementErr != nil {
70				// An already-connected (or disconnected — the opt-out keeps its
71				// coordinates) repo stays re-connectable without flags: re-connect
72				// means re-sync, not re-resolve.
73				if existing, present, readErr := readHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
74					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
75				} else {
76					return fmt.Errorf("connect: resolve hosted placement (`entire repo view --json`): %w; pass --repo-id and --api-url explicitly", placementErr)
77				}
78			}
79			if repoID == "" {
80				repoID = resolved.RepoID
81			}
82			if apiURL == "" {
83				apiURL = resolved.APIURL
84			}
85		}
86		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
87		if err != nil {
88			return fmt.Errorf("connect: %w", err)
89		}
90		out := cmd.OutOrStdout()
91		render := tui.NewRenderer(out)
92		fmt.Fprintf(out, "%s %s\n\n", render.Mark(tui.MarkDone),
93			render.Bold("Connected: repo "+binding.RepoID+" is now syncing memories"))
94		fmt.Fprintln(out, render.Dim("  Memories sync periodically and at session end. Teammates' memories merge into this repo's local brain."))
95		// Connect doubles as the initial pull so a fresh clone receives team
96		// memories immediately; failures note and never fail the connect.
97		return hostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, hostedSyncBranch(ctx, opts.Runner, repoDir))
98	}
99	
100	// bindHostedRepo validates and normalizes the target, then writes the
101	// repo-level binding. Cell URLs are commonly quoted with their /api/v1 prefix
102	// (repo view's apiUrl, docs examples), but the factsync client appends
103	// /api/v1/repos/... itself — storing the suffix would 404 every sync.
104	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
105		if strings.TrimSpace(repoID) == "" {
106			return hostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
107		}
108		validated, err := apiurl.Validate(apiURL)
109		if err != nil {
110			return hostedRepoBinding{}, err
111		}
112		binding := hostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}
113		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
114			return hostedRepoBinding{}, err
115		}
116		return binding, nil
117	}
118	
119	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
120	// placement.
121	func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
122		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
123		defer cancel()
124		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "view", "--json")
125		if err != nil {
126			return hostedPlacement{}, err
127		}
128		var result hostedPlacement
129		if err := decodeHostCLIJSON(stdout, &result); err != nil {
130			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
131		}
132		return result, nil
133	}

