48		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
49			fake.mu.Lock()
50			defer fake.mu.Unlock()
51			fake.requests++
52			w.Header().Set("Content-Type", "application/json")
53			switch {
54			case strings.Contains(r.URL.Path, "/brain/facts/proposals"):
55				w.WriteHeader(http.StatusNotFound)
56			case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
57				resp := map[string]any{"found": fake.ref != "", "ref": fake.ref, "version": 1, "data": fake.data}
58				if fake.authors != nil {
