60				}
61				_ = json.NewEncoder(w).Encode(resp)
62			case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts/advance"):
63				var body struct {
64					Branch string `json:"branch"`
65					OldRef string `json:"oldRef"`
